(defn with-service-binding
  "Establish a runtime dependency from a container to a network service.\n\nThe service will be started automatically when needed and detached when it is no longer needed, executing the default command if none is set.\n\nThe service will be reachable from the container via the provided hostname alias.\n\nThe service dependency will also convey to any files or directories produced by the container."
  [self arg-alias arg-service]
  (let [arguments {:alias arg-alias, :service arg-service}]
    (runtime/invoke-field self "Container" "withServiceBinding" arguments)))

(defn with-default-terminal-cmd
  "Set the default command to invoke for the container's terminal API.\nDeprecated: Use withShell.\nOptions: :disable-dagger-in-dagger, :experimental-privileged-nesting, :insecure-root-capabilities"
