(defn with-gpu
  "Configures all GPUs available on the host to be accessible to this container.\n\nThis currently works with NVIDIA devices only, and requires the engine to run with GPU support enabled."
  [self]
  (let [arguments {}] (runtime/invoke-field self "Container" "withGPU" arguments)))

(defn experimental-with-gpu
